"""Presentation-only weekly Monster hero. No picks, models, or database access."""

MONSTER_HERO_HTML = '\n{% set featured_trial = namespace(ticket=none) %}\n{% if available | default(false) %}\n    {% for ticket in active_tickets | default([]) | sort(attribute=\'id\', reverse=true) %}\n        {% if featured_trial.ticket is none\n              and ticket.is_trial | default(false)\n              and ticket.outcome == \'PENDING\' %}\n            {% set featured_trial.ticket = ticket %}\n        {% endif %}\n    {% endfor %}\n{% endif %}\n\n<style>\n.monster-hero {\n    position: relative;\n    overflow: hidden;\n    margin: 0 0 28px;\n    padding: 26px;\n    border: 2px solid #39ff88;\n    border-radius: 22px;\n    background: linear-gradient(145deg, #071c12, #101714 65%, #072516);\n    box-shadow: 0 0 24px #39ff8833, inset 0 0 28px #39ff8810;\n    color: #e8fff0;\n}\n.monster-hero * { box-sizing: border-box; }\n.monster-eyebrow {\n    margin: 0 0 8px;\n    color: #71ffa8;\n    font-size: 12px;\n    letter-spacing: .18em;\n    text-transform: uppercase;\n}\n.monster-hero h2 {\n    margin: 0;\n    color: #71ffa8;\n    font-size: clamp(26px, 5vw, 42px);\n    text-shadow: 0 0 16px #39ff8855;\n}\n.monster-intro {\n    margin: 10px 0 22px;\n    color: #bfd8c9;\n    line-height: 1.6;\n}\n.monster-machine {\n    display: grid;\n    grid-template-columns: 1fr 150px 1fr;\n    gap: 14px;\n    padding: 16px;\n    border: 1px solid #39ff8844;\n    border-radius: 16px;\n    background: #030b07;\n}\n.monster-reel {\n    display: flex;\n    min-height: 150px;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    padding: 14px;\n    border: 1px solid #39ff8833;\n    border-radius: 12px;\n    background: linear-gradient(#0b2115, #07110b);\n    text-align: center;\n}\n.monster-reel-label {\n    color: #a2bfae;\n    font-size: 11px;\n    letter-spacing: .12em;\n    text-transform: uppercase;\n}\n.monster-reel-value {\n    margin: 10px 0;\n    color: #71ffa8;\n    font-size: 22px;\n    font-weight: 700;\n}\n.monster-reel-note { color: #a2bfae; font-size: 12px; }\n.monster-face {\n    position: relative;\n    width: 100px;\n    height: 100px;\n    border: 3px solid #71ffa8;\n    border-radius: 50%;\n    background: #102a1b;\n    box-shadow: 0 0 22px #39ff8855;\n    animation: monster-spin 8s linear infinite;\n}\n.monster-eyes {\n    position: absolute;\n    top: 17px;\n    left: 0;\n    right: 0;\n    color: #71ffa8;\n    font-size: 29px;\n    font-weight: 800;\n    letter-spacing: 9px;\n    padding-left: 9px;\n}\n.monster-smile {\n    position: absolute;\n    bottom: 19px;\n    left: 25px;\n    width: 44px;\n    height: 23px;\n    border-bottom: 4px solid #71ffa8;\n    border-radius: 0 0 40px 40px;\n}\n.monster-status {\n    margin: 20px 0 8px;\n    color: #e8fff0;\n    font-size: 17px;\n    font-weight: 700;\n}\n.monster-disclaimer {\n    margin: 0;\n    color: #a2bfae;\n    font-size: 13px;\n    line-height: 1.6;\n}\n@keyframes monster-spin {\n    from { transform: rotate(0deg); }\n    to { transform: rotate(360deg); }\n}\n@media (max-width: 600px) {\n    .monster-hero { padding: 18px; }\n    .monster-machine { grid-template-columns: 1fr; }\n    .monster-reel { min-height: 110px; }\n    .monster-center { grid-row: 1; min-height: 145px; }\n}\n@media (prefers-reduced-motion: reduce) {\n    .monster-face { animation: none; }\n}\n</style>\n\n<section class="monster-hero" aria-labelledby="monster-title">\n    <p class="monster-eyebrow">Weekly showcase</p>\n    <h2 id="monster-title">🎰 Weekly Monster</h2>\n    <p class="monster-intro">\n        Your weekly ticket showcase.\n    </p>\n\n    <div class="monster-machine">\n        <div class="monster-reel">\n            <span class="monster-reel-label">Ticket</span>\n            <span class="monster-reel-value">{% if featured_trial.ticket %}\n        Ticket #{{ featured_trial.ticket.id }}\n        {% else %}Coming soon{% endif %}</span>\n            <span class="monster-reel-note">{% if featured_trial.ticket %}\n        {{ featured_trial.ticket.legs | length }} legs · Trial\n        {% else %}No ticket available{% endif %}</span>\n        </div>\n\n        <div class="monster-reel monster-center">\n            <div class="monster-face" aria-hidden="true">\n                <span class="monster-eyes">&#36;&#36;</span>\n                <span class="monster-smile"></span>\n            </div>\n        </div>\n\n        <div class="monster-reel">\n            <span class="monster-reel-label">Estimated simulated return</span>\n            <span class="monster-reel-value">{% if featured_trial.ticket %}\n        {{ featured_trial.ticket.payout }}\n        {% else %}—{% endif %}</span>\n            <span class="monster-reel-note">{% if featured_trial.ticket %}\n        Simulated stake {{ featured_trial.ticket.stake }}\n        {% else %}Available when a ticket is published{% endif %}</span>\n        </div>\n    </div>\n\n    {% if featured_trial.ticket %}\n    <p class="monster-status">Featured trial ticket · Pending</p>\n    <ul class="monster-legs">\n        {% for leg in featured_trial.ticket.legs %}\n        <li>{{ leg }}</li>\n        {% endfor %}\n    </ul>\n    <p class="monster-disclaimer">\n        Not validated · Simulated returns.\n        Published {{ featured_trial.ticket.created }}.\n    </p>\n    {% else %}\n    <p class="monster-status">Waiting for a weekly ticket.</p>\n    <p class="monster-disclaimer">\n        Preview only. No ticket or return is available.\n    </p>\n    {% endif %}\n</section>\n'


def add_monster_hero(template):
    """Insert once at the top of the dashboard's main content."""
    if 'id="monster-title"' in template:
        return template
    if template.count("<main>") != 1:
        raise ValueError("Expected exactly one dashboard main element")
    return template.replace("<main>", "<main>" + MONSTER_HERO_HTML, 1)
